import { archetypes, Archetype } from './data';

export const calculateResult = (answers: number[], maskMode: boolean): Archetype => {
  const totalScore = answers.reduce((sum, answer) => sum + answer, 0);
  let averageScore = totalScore / answers.length;

  if (maskMode) {
    averageScore += 0.3;
  }

  if (averageScore <= 1.4) return archetypes["The Ghost Mirror"];
  if (averageScore <= 1.9) return archetypes["The Grounded"];
  if (averageScore <= 2.4) return archetypes["The Observer"];
  if (averageScore <= 2.9) return archetypes["The Balancer"];
  if (averageScore <= 3.4) return archetypes["The Performer"];
  if (averageScore <= 3.9) return archetypes["The Strategist"];
  if (averageScore <= 4.4) return archetypes["The Mirror Prince/Princess"];
  if (averageScore <= 4.7) return archetypes["The Wounded God"];
  return archetypes["The Void Mirror"];
};
