import React, { useState } from 'react';
import { Question, questions, metaQuestionOptions } from '../data';

// Define gtag on the window object to avoid TypeScript errors
declare global {
  interface Window {
    gtag?: (type: string, eventName: string, eventParams: object) => void;
  }
}

interface Props {
  onComplete: (answers: number[], maskMode: boolean) => void;
}

const Questionnaire: React.FC<Props> = ({ onComplete }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<number[]>([]);
  const [maskMode, setMaskMode] = useState(false);

  const handleAnswer = (answer: number) => {
    // Don't track the meta question as a numbered answer
    if (currentQuestionIndex > 0 && window.gtag) {
        window.gtag('event', 'answer_question', {
            event_category: 'mirror_test',
            event_label: `Question ${currentQuestionIndex} answered`,
            question_number: currentQuestionIndex,
            answer_value: answer,
        });
    }

    if (currentQuestionIndex === 0) {
      if (answer === 2) {
        setMaskMode(true);
      }
      setCurrentQuestionIndex(currentQuestionIndex + 1);
      return;
    }

    const newAnswers = [...answers, answer];
    setAnswers(newAnswers);

    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    } else {
      onComplete(newAnswers, maskMode);
    }
  };

  const currentQuestion = questions[currentQuestionIndex];
  const progress = (currentQuestionIndex / questions.length) * 100;

  return (
    <div className="card text-white bg-dark my-5">
        <div className="card-body p-5">
            <div className="progress mb-4">
                <div className="progress-bar" role="progressbar" style={{width: `${progress}%`}} aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100}></div>
            </div>
            <h2 className="h4 mb-4">{currentQuestion.text}</h2>
            
            {currentQuestionIndex === 0 ? (
                <div className="d-grid gap-2 col-6 mx-auto">
                    <button className="btn btn-outline-light" onClick={() => handleAnswer(1)}>{metaQuestionOptions[0]}</button>
                    <button className="btn btn-outline-light" onClick={() => handleAnswer(2)}>{metaQuestionOptions[1]}</button>
                </div>
            ) : (
                <div className="d-flex justify-content-center align-items-center">
                    <span className="me-3">Strongly Disagree</span>
                    {[1, 2, 3, 4, 5].map(value => (
                        <button key={value} className="btn btn-outline-primary mx-2" onClick={() => handleAnswer(value)}>{value}</button>
                    ))}
                    <span className="ms-3">Strongly Agree</span>
                </div>
            )}
            <p className="text-muted mt-4">Section: {currentQuestion.section}</p>
        </div>
    </div>
  );
};

export default Questionnaire;
