import React, { useState } from 'react';
import './App.css';
import WelcomeScreen from './components/WelcomeScreen';
import Questionnaire from './components/Questionnaire';
import ResultsScreen from './components/ResultsScreen';
import { calculateResult } from './utils';
import { Archetype } from './data';

// Define gtag on the window object to avoid TypeScript errors
declare global {
  interface Window {
    gtag?: (type: string, eventName: string, eventParams: object) => void;
  }
}

function App() {
  const [appState, setAppState] = useState('welcome');
  const [answers, setAnswers] = useState<number[]>([]);
  const [maskMode, setMaskMode] = useState(false);
  const [result, setResult] = useState<Archetype | null>(null);

  const handleStart = () => {
    if (window.gtag) {
      window.gtag('event', 'start_test', {
        event_category: 'mirror_test',
        event_label: 'User started test',
      });
    }
    setAppState('questionnaire');
  };

  const handleComplete = (finalAnswers: number[], finalMaskMode: boolean) => {
    const finalResult = calculateResult(finalAnswers, finalMaskMode);
    const averageScore = finalAnswers.reduce((sum, answer) => sum + answer, 0) / finalAnswers.length;

    if (window.gtag) {
      window.gtag('event', 'finish_test', {
        event_category: 'mirror_test',
        event_label: 'Test completed',
        score: parseFloat(averageScore.toFixed(2)),
        archetype: finalResult.title,
      });
    }

    setAnswers(finalAnswers);
    setMaskMode(finalMaskMode);
    setResult(finalResult);
    setAppState('results');
  };

  const handleRestart = () => {
    if (window.gtag) {
      window.gtag('event', 'restart_test', {
          event_category: 'mirror_test',
          event_label: 'User restarted test',
      });
    }
    setAnswers([]);
    setMaskMode(false);
    setResult(null);
    setAppState('welcome');
  };

  return (
    <div className="App">
      {appState === 'welcome' && <WelcomeScreen onStart={handleStart} />}
      {appState === 'questionnaire' && <Questionnaire onComplete={handleComplete} />}
      {appState === 'results' && <ResultsScreen result={result} onRestart={handleRestart} />}
    </div>
  );
}

export default App;